"""Context manager that logs function entry, exit, and execution time."""

import logging
import time
from contextlib import contextmanager
from functools import wraps

logging.basicConfig(level=logging.INFO, format="%(asctime)s - %(name)s - %(levelname)s - %(message)s")
logger = logging.getLogger("function_logger")


class FunctionTimer:
    """Context manager that logs entry, exit, and elapsed time."""

    def __init__(self, name: str, log_level: int = logging.INFO):
        self.name = name
        self.log_level = log_level
        self.elapsed: float = 0.0

    def __enter__(self):
        logger.log(self.log_level, "[%s] entered", self.name)
        self._start = time.perf_counter()
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        self.elapsed = time.perf_counter() - self._start
        if exc_type:
            logger.log(self.log_level, "[%s] exited with %s (%.4fs)", self.name, exc_type.__name__, self.elapsed)
        else:
            logger.log(self.log_level, "[%s] exited (%.4fs)", self.name, self.elapsed)
        return False  # don't suppress exceptions


@contextmanager
def log_function(name: str, log_level: int = logging.INFO):
    """Generator-based alternative to FunctionTimer."""
    logger.log(log_level, "[%s] entered", name)
    start = time.perf_counter()
    try:
        yield
    except Exception:
        elapsed = time.perf_counter() - start
        logger.log(log_level, "[%s] exited with exception (%.4fs)", name, elapsed)
        raise
    else:
        elapsed = time.perf_counter() - start
        logger.log(log_level, "[%s] exited (%.4fs)", name, elapsed)


def logged(func=None, *, log_level: int = logging.INFO):
    """Decorator that wraps a function body in FunctionTimer."""
    def decorator(fn):
        @wraps(fn)
        def wrapper(*args, **kwargs):
            with FunctionTimer(fn.__name__, log_level=log_level):
                return fn(*args, **kwargs)
        return wrapper

    if func is not None:
        return decorator(func)
    return decorator


if __name__ == "__main__":
    # Example 1: class-based context manager
    with FunctionTimer("example block"):
        time.sleep(0.1)

    # Example 2: generator-based context manager
    with log_function("another block"):
        time.sleep(0.05)

    # Example 3: decorator
    @logged
    def compute(n):
        return sum(i * i for i in range(n))

    compute(1_000_000)

    # Example 4: decorator with custom log level
    @logged(log_level=logging.DEBUG)
    def debug_task():
        time.sleep(0.02)

    debug_task()

"""Tests for function_logger."""

import logging
import time

import pytest

from function_logger import FunctionTimer, log_function, logged


@pytest.fixture
def log_records(caplog):
    caplog.set_level(logging.DEBUG, logger="function_logger")
    return caplog


# --- FunctionTimer ---

class TestFunctionTimer:
    def test_logs_entry_and_exit(self, log_records):
        with FunctionTimer("task"):
            pass
        messages = [r.message for r in log_records.records]
        assert "[task] entered" in messages[0]
        assert "[task] exited" in messages[1]

    def test_measures_elapsed_time(self, log_records):
        with FunctionTimer("task") as timer:
            time.sleep(0.05)
        assert timer.elapsed >= 0.04

    def test_logs_exception_type_on_failure(self, log_records):
        with pytest.raises(ValueError):
            with FunctionTimer("boom"):
                raise ValueError("bad")
        messages = [r.message for r in log_records.records]
        assert any("ValueError" in m for m in messages)

    def test_does_not_suppress_exception(self):
        with pytest.raises(RuntimeError):
            with FunctionTimer("fail"):
                raise RuntimeError("nope")


# --- log_function ---

class TestLogFunction:
    def test_logs_entry_and_exit(self, log_records):
        with log_function("task"):
            pass
        messages = [r.message for r in log_records.records]
        assert "[task] entered" in messages[0]
        assert "[task] exited" in messages[1]

    def test_logs_exception_on_failure(self, log_records):
        with pytest.raises(KeyError):
            with log_function("oops"):
                raise KeyError("missing")
        messages = [r.message for r in log_records.records]
        assert any("exception" in m for m in messages)

    def test_does_not_suppress_exception(self):
        with pytest.raises(TypeError):
            with log_function("fail"):
                TypeError("no")


# --- logged decorator ---

class TestLogged:
    def test_decorates_function(self, log_records):
        @logged
        def add(a, b):
            return a + b

        result = add(2, 3)
        assert result == 5
        messages = [r.message for r in log_records.records]
        assert any("add" in m and "entered" in m for m in messages)
        assert any("add" in m and "exit" in m for m in messages)

    def test_preserves_function_name(self):
        @logged
        def original_name():
            pass

        assert original_name.__name__ == "original_name"

    def test_custom_log_level(self, log_records):
        @logged(log_level=logging.DEBUG)
        def quiet():
            return 42

        result = quiet()
        assert result == 42

    def test_passes_args_and_kwargs(self, log_records):
        @logged
        def greet(name, greeting="hello"):
            return f"{greeting} {name}"

        assert greet("world", greeting="hi") == "hi world"

    def test_propagates_exceptions(self, log_records):
        @logged
        def bad():
            raise RuntimeError("oops")

        with pytest.raises(RuntimeError, match="oops"):
            bad()
